-- Preserve every legacy reservation while introducing one canonical v2 assignment per account.
LOCK TABLE public.gyvora_id_registry, public.profiles, public.gyms, public.gym_records IN ACCESS EXCLUSIVE MODE;
ALTER TABLE public.gyvora_id_registry ADD COLUMN identity_version integer NOT NULL DEFAULT 1;
ALTER TABLE public.gyvora_id_registry DROP CONSTRAINT gyvora_id_registry_number_check;
ALTER TABLE public.gyvora_id_registry ADD CONSTRAINT gyvora_number_format CHECK(number ~ '^[1-9][0-9]{2,}$');
ALTER TABLE public.gyvora_id_registry DROP CONSTRAINT gyvora_id_registry_kind_account_id_key;
ALTER TABLE public.gyvora_id_registry ADD CONSTRAINT gyvora_account_version_unique UNIQUE(kind,account_id,identity_version);
ALTER TABLE public.gyvora_id_registry ADD CONSTRAINT gyvora_version_check CHECK(identity_version IN (1,2));
CREATE TABLE public.gyvora_allocator_state (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), lower_bound text NOT NULL DEFAULT '100' CHECK(lower_bound ~ '^10{2,}$'));
GRANT ALL ON public.gyvora_allocator_state TO service_role;
ALTER TABLE public.gyvora_allocator_state ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.gyvora_next_number(value text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE i integer:=length(value); result text:=value; BEGIN WHILE i>0 AND substr(result,i,1)='9' LOOP result:=overlay(result placing '0' from i for 1); i:=i-1; END LOOP; IF i=0 THEN RETURN '1'||result; END IF; RETURN overlay(result placing (substr(result,i,1)::integer+1)::text from i for 1); END $$;
REVOKE ALL ON FUNCTION public.gyvora_next_number(text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.allocate_gyvora_id(k text,a uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result text; candidate text; first_candidate text; lower_value text; digit_count integer; i integer; BEGIN IF k NOT IN ('G','C') OR a IS NULL THEN RAISE EXCEPTION 'Invalid account identity'; END IF; PERFORM pg_advisory_xact_lock(716426031); SELECT gyvora_id INTO result FROM public.gyvora_id_registry WHERE kind=k AND account_id=a AND identity_version=2; IF result IS NOT NULL THEN RETURN result; END IF; INSERT INTO public.gyvora_allocator_state(singleton) VALUES(true) ON CONFLICT DO NOTHING; LOOP SELECT lower_bound INTO lower_value FROM public.gyvora_allocator_state WHERE singleton FOR UPDATE; digit_count:=length(lower_value); candidate:=(1+floor(random()*9)::integer)::text; FOR i IN 2..digit_count LOOP candidate:=candidate||floor(random()*10)::integer::text; END LOOP; first_candidate:=candidate; LOOP INSERT INTO public.gyvora_id_registry(number,kind,account_id,identity_version) VALUES(candidate,k,a,2) ON CONFLICT DO NOTHING RETURNING gyvora_id INTO result; IF result IS NOT NULL THEN RETURN result; END IF; candidate:=public.gyvora_next_number(candidate); IF length(candidate)>digit_count THEN candidate:=lower_value; END IF; EXIT WHEN candidate=first_candidate; END LOOP; UPDATE public.gyvora_allocator_state SET lower_bound=lower_bound||'0' WHERE singleton; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.allocate_gyvora_id(text,uuid) FROM PUBLIC,anon,authenticated;
-- Migration-only trigger accepts precisely the database-allocated replacement. Exclusive locks prevent concurrent writes.
CREATE OR REPLACE FUNCTION public.assign_gyvora_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; BEGIN k:=CASE WHEN TG_TABLE_NAME='gyms' THEN 'G' ELSE 'C' END; IF TG_OP='UPDATE' AND NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Permanent account identity cannot be changed'; END IF; IF TG_TABLE_NAME='gyms' OR (to_jsonb(NEW)->>'account_type') IN ('client','staff') THEN NEW.gyvora_id:=public.allocate_gyvora_id(k,NEW.id); ELSIF TG_OP='INSERT' THEN NEW.gyvora_id:=NULL; END IF; RETURN NEW; END $$;
-- Additive reservation backfill includes retained/deleted and opaque Local demo accounts.
DO $$ DECLARE r record; BEGIN FOR r IN SELECT kind,account_id FROM public.gyvora_id_registry WHERE identity_version=1 ORDER BY assigned_at,number LOOP PERFORM public.allocate_gyvora_id(r.kind,r.account_id); END LOOP; END $$;
UPDATE public.gyms SET gyvora_id=public.allocate_gyvora_id('G',id);
UPDATE public.profiles SET gyvora_id=public.allocate_gyvora_id('C',id) WHERE account_type IN ('client','staff') OR gyvora_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.assign_gyvora_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; BEGIN IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR (OLD.gyvora_id IS NOT NULL AND NEW.gyvora_id IS DISTINCT FROM OLD.gyvora_id)) THEN RAISE EXCEPTION 'Permanent account identity cannot be changed'; END IF; k:=CASE WHEN TG_TABLE_NAME='gyms' THEN 'G' ELSE 'C' END; IF TG_TABLE_NAME='gyms' OR (to_jsonb(NEW)->>'account_type') IN ('client','staff') THEN NEW.gyvora_id:=public.allocate_gyvora_id(k,NEW.id); ELSIF TG_OP='INSERT' THEN NEW.gyvora_id:=NULL; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_gyvora_identity() FROM PUBLIC,anon,authenticated;
-- Refresh only the canonical QR field in retained membership snapshots.
ALTER TABLE public.gym_records DISABLE TRIGGER USER;
UPDATE public.gym_records r SET data=jsonb_set(r.data,'{gyvoraId}',to_jsonb(p.gyvora_id)) FROM public.profiles p WHERE r.kind='members' AND r.client_id=p.id AND p.gyvora_id IS NOT NULL;
ALTER TABLE public.gym_records ENABLE TRIGGER USER;
COMMENT ON COLUMN public.gyvora_id_registry.identity_version IS 'Version 1 reservations remain permanently retired; version 2 is the immutable growing-digit canonical assignment.';
COMMENT ON FUNCTION public.allocate_gyvora_id(text,uuid) IS 'Shared atomic text-based allocator: random circular free-slot search, exhausting each digit length before growth. No application suffix-length cap; database text/index/storage limits still apply.';